const items = $input.all();

if (!items.length || !items[0].json || Object.keys(items[0].json).length === 0 || !items[0].json.domicilio) {
  return [{
    json: {
      encontrado: false,
      user_domicilios: [],
      user_domicilios_lista: []
    }
  }];
}

const mapaDomicilios = {};

items.forEach(item => {
  if (item.json && item.json.domicilio) {
    const domLimpio = String(item.json.domicilio).trim().toUpperCase();
    const servicio = item.json.tipo_servicio ? String(item.json.tipo_servicio).trim().toUpperCase() : null;

    if (!mapaDomicilios[domLimpio]) {
      mapaDomicilios[domLimpio] = {
        domicilio: domLimpio,
        servicios: []
      };
    }

    if (servicio && !mapaDomicilios[domLimpio].servicios.includes(servicio)) {
      mapaDomicilios[domLimpio].servicios.push(servicio);
    }
  }
});

const listaDomiciliosObjetos = [];
const listaDomiciliosTextos = [];

Object.values(mapaDomicilios).forEach(item => {
  const detalle = item.servicios.length > 0 ? item.servicios.join(", ") : "";
  const labelVisual = detalle ? `${item.domicilio} (${detalle})` : item.domicilio;

  listaDomiciliosObjetos.push({
    label: labelVisual,
    value: item.domicilio,
    domicilio: item.domicilio
  });

  listaDomiciliosTextos.push(labelVisual);
});

return [{
  json: {
    encontrado: true,
    user_domicilios: listaDomiciliosTextos,
    user_domicilios_lista: listaDomiciliosObjetos,
    cantidad_resultados: listaDomiciliosTextos.length
  }
}];

const items = $input.all();

// 1. Validamos si no hay resultados
if (!items.length || !items[0].json || Object.keys(items[0].json).length === 0) {
  return [{ json: { valido: false } }];
}

// 2. Extraemos nombre y email
const primerRegistroConNombre = items.find(item => item.json && item.json.nombre);
const nombreAsociado = primerRegistroConNombre ? primerRegistroConNombre.json.nombre : '';

const primerRegistroConEmail = items.find(item => item.json && item.json.email);
const emailAsociado = primerRegistroConEmail ? primerRegistroConEmail.json.email : '';

// 3. Agrupamos por Domicilio Único
const mapaDomicilios = {};

items.forEach(item => {
  if (item.json && item.json.domicilio) {
    const domLimpio = String(item.json.domicilio).trim().toUpperCase();
    const codigoUser = item.json.Codigo;
    const servicio = item.json.tipo_servicio ? String(item.json.tipo_servicio).trim().toUpperCase() : null;

    if (!mapaDomicilios[domLimpio]) {
      mapaDomicilios[domLimpio] = {
        domicilio: domLimpio,
        codigos: [],
        codigosInternet: [],
        servicios: []
      };
    }

    if (codigoUser && !mapaDomicilios[domLimpio].codigos.includes(codigoUser)) {
      mapaDomicilios[domLimpio].codigos.push(codigoUser);
    }

    // Capturamos de forma específica el código si corresponde al servicio de internet
    if (servicio === 'INTERNET' && codigoUser) {
      if (!mapaDomicilios[domLimpio].codigosInternet.includes(codigoUser)) {
        mapaDomicilios[domLimpio].codigosInternet.push(codigoUser);
      }
    }

    if (servicio && !mapaDomicilios[domLimpio].servicios.includes(servicio)) {
      mapaDomicilios[domLimpio].servicios.push(servicio);
    }
  }
});

// 4. Armamos la estructura de salida para los botones de Typebot
const listaDomiciliosObjetos = [];
const listaDomiciliosTextos = [];

Object.values(mapaDomicilios).forEach(item => {
  let detalle = "";
  if (item.servicios.length > 0) {
    detalle = item.servicios.join(", ");
  }

  const labelVisual = detalle ? item.domicilio + " (" + detalle + ")" : item.domicilio;

  // Tomamos estrictamente el código de internet si existe, caso contrario el primero disponible
  const codigoPreciso = item.codigosInternet.length > 0 ? item.codigosInternet[0] : (item.codigos[0] || null);

  listaDomiciliosObjetos.push({
    label: labelVisual,
    value: item.domicilio,
    domicilio: item.domicilio,
    codigo: codigoPreciso
  });

  listaDomiciliosTextos.push(labelVisual);
});

// 5. Medidores y códigos específicos
const medidorEnergia = items.find(item => item.json?.tipo_servicio === 'energia' && item.json?.medidor)?.json.medidor || null;
const medidorAgua = items.find(item => item.json?.tipo_servicio === 'agua' && item.json?.medidor)?.json.medidor || null;

// Buscamos estrictamente el primer código de internet disponible para el usuario, sino el primero general
const registroInternet = items.find(item => item.json?.tipo_servicio === 'internet');
const codigoPrincipal = registroInternet ? registroInternet.json.Codigo : (items.find(item => item.json && item.json.Codigo)?.json.Codigo || null);

return [{
  json: {
    valido: true,
    user_nombre: nombreAsociado,
    user_email: emailAsociado,
    user_codigo: codigoPrincipal, // <--- Ahora tomará el 6 en lugar del 14
    user_domicilios: listaDomiciliosTextos,
    user_domicilios_lista: listaDomiciliosObjetos,
    cantidad_domicilios: listaDomiciliosTextos.length,
    medidor_energia: medidorEnergia,
    medidor_agua: medidorAgua
  }
}];

// Validación de entrada (H-01): solo dígitos en números, comillas escapadas en texto
const NUMERICOS = ["telefono"];
const TEXTOS    = [];
const MOTOR     = 'mssql';
const LARGO_MIN = {"telefono": 10};

const entrada = $input.first().json;
const body = { ...(entrada.body || {}) };

for (const campo of NUMERICOS) {
  const limpio = String(body[campo] ?? '').trim().replace(/[\s.\-()+]/g, '');
  const minimo = LARGO_MIN[campo] || 1;
  if (!/^\d+$/.test(limpio) || limpio.length < minimo || limpio.length > 15) {
    throw new Error(`Entrada inválida en el campo "${campo}"`);
  }
  body[campo] = limpio;
}

for (const campo of TEXTOS) {
  let texto = String(body[campo] ?? '').trim().slice(0, 200);
  if (MOTOR === 'mysql') texto = texto.replace(/\\/g, '\\\\');
  body[campo] = texto.replace(/'/g, "''");
}

return [{ json: { ...entrada, body } }];

